-- DIRA LEARN - installation in the Supabase SQL Editor, STEP 5 of 5: read-only verification (changes nothing)
-- Generated by tools/baseline/build_install.py from supabase/production_init/02_verify_readonly.sql - do not edit by hand.
-- Every row must say ok and the last row READY. After the first Super Administrator exists, checks 7 and 8 change by design.

with
hist as (
  select case when to_regclass('supabase_migrations.schema_migrations') is null then null
              else (xpath('/row/v/text()', query_to_xml(
                     'select string_agg(version, '','' order by version) as v from supabase_migrations.schema_migrations', false, true, '')))[1]::text end as v),
t as (select count(*) as n, count(*) filter (where not relrowsecurity) as no_rls,
             string_agg(relname, ', ') filter (where not relrowsecurity) as no_rls_names
        from pg_class where relnamespace = 'public'::regnamespace and relkind in ('r', 'p')),
checks(ord, item, ok, detail) as (
  select 1, 'DIRA LEARN baseline installed completely (STEPS 1-4; history = the 3 baseline versions)',
         (select v from hist) = '20261121000001,20261121000002,20261121000003'
         and (select string_agg(step::text, ',' order by step) from supabase_migrations.dira_install_steps) = '1,2,3,4',
         coalesce((select v from hist), 'no history table')
  union all
  select 2, 'public tables (100 expected; 106 once the Chat change of 22 Nov 2026 is applied), all with Row Level Security',
         (select n = 100 + case when to_regclass('public.connect_members') is not null then 6 else 0 end and no_rls = 0 from t),
         (select n || ' tables; without RLS: ' || coalesce(no_rls_names, 'none') from t)
  union all
  select 3, 'public.profiles exists', to_regclass('public.profiles') is not null, coalesce(to_regclass('public.profiles')::text, 'MISSING')
  union all
  select 4, 'sign-up trigger on_auth_user_created enabled',
         exists (select 1 from pg_trigger where tgrelid = 'auth.users'::regclass and tgname = 'on_auth_user_created' and tgenabled <> 'D'),
         coalesce((select 'tgenabled=' || tgenabled::text from pg_trigger where tgrelid = 'auth.users'::regclass and tgname = 'on_auth_user_created'), 'MISSING')
  union all
  select 5, 'every sign-in account has a profile',
         not exists (select 1 from auth.users u where not exists (select 1 from public.profiles p where p.id = u.id)),
         (select count(*) from auth.users) || ' accounts, ' ||
         (select count(*) from auth.users u where not exists (select 1 from public.profiles p where p.id = u.id)) || ' without a profile'
  union all
  select 6, 'no orphan profiles (profile without account)',
         not exists (select 1 from public.profiles p where not exists (select 1 from auth.users u where u.id = p.id)),
         (select count(*) from public.profiles) || ' profiles'
  union all
  select 7, 'nobody above applicant yet (before the first-admin claim)',
         not exists (select 1 from public.profiles where role <> 'applicant'),
         coalesce((select string_agg(role || ' ' || n, ', ') from (select role::text, count(*) n from public.profiles group by 1) r), 'no profiles')
  union all
  select 8, 'first_admin_needed() is true', public.first_admin_needed(), 'claim via /setup is possible exactly once'
  union all
  select 9, 'claim_first_admin() not callable from the browser',
         not has_function_privilege('authenticated', 'public.claim_first_admin(uuid)', 'execute')
         and not has_function_privilege('anon', 'public.claim_first_admin(uuid)', 'execute'), 'service role only'
  union all
  select 10, 'signed-out visitors can call only check_request and verify_certificate',
         coalesce((select string_agg(proname, ',' order by proname) from pg_proc p
                    where pronamespace = 'public'::regnamespace and prorettype not in ('trigger'::regtype, 'event_trigger'::regtype)
                      and has_function_privilege('anon', p.oid, 'execute')), '') = 'check_request,verify_certificate',
         coalesce((select string_agg(proname, ',' order by proname) from pg_proc p
                    where pronamespace = 'public'::regnamespace and prorettype not in ('trigger'::regtype, 'event_trigger'::regtype)
                      and has_function_privilege('anon', p.oid, 'execute')), 'none')
  union all
  select 11, 'API account-status check installed (migration 34)',
         exists (select 1 from pg_roles where rolname = 'authenticator' and 'pgrst.db_pre_request=public.check_request' = any(rolconfig)),
         coalesce((select array_to_string(rolconfig, ' ') from pg_roles where rolname = 'authenticator'), 'none')
  union all
  select 12, 'six private storage buckets',
         (select count(*) = 6 and count(*) filter (where public) = 0 from storage.buckets
           where id in ('application-documents', 'connect-attachments', 'course-materials', 'learning-resources', 'project-evidence', 'submissions')),
         (select count(*) || ' buckets, public: ' || count(*) filter (where public) from storage.buckets)
  union all
  select 13, 'curriculum structure: 4 tracks (Digital Marketing, AI Tools, Content Creation, Entrepreneurship & Business); 2 core sessions (week 1) + 6 sessions (3-8, weeks 2-4) per track = 26 records',
         (select count(*) from public.organizations) = 1 and (select count(*) from public.programmes) = 1
         and (select string_agg(code || '=' || name, ',' order by position) from public.tracks)
             = 'digital=Digital Marketing,ai=AI Tools,content=Content Creation,entrepreneurship=Entrepreneurship & Business'
         and (select count(*) from public.curriculum_sessions where track_id is null and week_no = 1 and session_no in (1, 2)) = 2
         and (select count(*) from public.curriculum_sessions where track_id is null) = 2
         and not exists (select 1 from public.tracks t
                          where (select count(*) from public.curriculum_sessions s
                                  where s.track_id = t.id and s.session_no between 3 and 8 and s.week_no between 2 and 4) <> 6)
         and (select count(*) from public.curriculum_sessions) = 26,
         'core ' || (select count(*) from public.curriculum_sessions where track_id is null) || ', per track ' ||
         coalesce((select string_agg(t.code || ' ' || (select count(*) from public.curriculum_sessions s where s.track_id = t.id), ', ' order by t.position)
                     from public.tracks t), 'none') || ', total ' || (select count(*) from public.curriculum_sessions)

  union all
  select 14, 'approval state as documented: only the Entrepreneurship 4 record approved; 26 lesson plans draft; programme not approved; all 24 topic proposals pending',
         (select string_agg(coalesce(t.code, 'core') || s.session_no, ',') from public.curriculum_sessions s left join public.tracks t on t.id = s.track_id where s.is_approved) = 'entrepreneurship4'
         and (select count(*) filter (where status::text = 'draft') = 26 and count(*) = 26 from public.curriculum_lesson_plans)
         and not exists (select 1 from public.programmes where is_approved)
         and (select count(*) = 24 and count(*) filter (where status::text = 'pending' and reviewed_at is null) = 24 from public.curriculum_topic_proposals),
         'approved records: ' || coalesce((select string_agg(coalesce(t.code, 'core') || ' ' || s.session_no, ', ') from public.curriculum_sessions s left join public.tracks t on t.id = s.track_id where s.is_approved), 'none')
         || '; plans: ' || (select string_agg(status::text || ' ' || n, ', ') from (select status, count(*) n from public.curriculum_lesson_plans group by 1) x)
         || '; programme approved: ' || coalesce((select bool_or(is_approved)::text from public.programmes), '-')
         || '; topics: ' || coalesce((select string_agg(status::text || ' ' || n, ', ') from (select status, count(*) n from public.curriculum_topic_proposals group by 1) x), 'none')
  union all
  select 15, 'Digital Marketing: the 11 topics approved by DIRA on 8 Nov 2026 sit on their V13.2 sessions (3,3,4,5,5,6,4,7,6,7,7), pending, approval noted; records 3-8 draft with the approval note; Entrepreneurship 4 proposals untouched',
         (select string_agg(p.title || '@' || s.session_no, '|' order by p.title)
            from public.curriculum_topic_proposals p join public.curriculum_sessions s on s.id = p.session_id join public.tracks t on t.id = p.track_id where t.code = 'digital')
           = 'Canva for marketing graphics@5|Content planning and creation@5|Developing a practical digital marketing strategy@7|Digital advertising fundamentals@7|Digital footprint and online safety@3|Introduction to digital marketing@3|Marketing analytics and measuring campaign performance@7|Marketing copywriting, captions and calls to action@6|SEO fundamentals@6|Social media marketing (Facebook, Instagram, TikTok, LinkedIn)@4|WhatsApp Business@4'
         and (select count(*) from public.curriculum_topic_proposals p join public.tracks t on t.id = p.track_id
               where t.code = 'digital' and p.status::text = 'pending' and p.description like 'Approved by DIRA on 8 Nov 2026 as a topic of Digital Marketing Session %') = 11
         and (select string_agg(s.session_no || '=' || cardinality(s.topics), ',' order by s.session_no) from public.curriculum_sessions s join public.tracks t on t.id = s.track_id where t.code = 'digital')
             = '3=2,4=2,5=2,6=2,7=3,8=0'
         and (select count(*) filter (where not is_approved and position('DIRA approval of 8 Nov 2026' in coalesce(assessment_notes, '')) > 0) = 6
              from public.curriculum_sessions s join public.tracks t on t.id = s.track_id where t.code = 'digital' and s.session_no between 3 and 8)
         and (select count(*) filter (where p.status::text = 'pending' and p.description is null) = 10 and count(*) = 10
              from public.curriculum_topic_proposals p join public.curriculum_sessions s on s.id = p.session_id join public.tracks t on t.id = p.track_id
              where t.code = 'entrepreneurship' and s.session_no = 4),
         'Digital Marketing topics per session: ' || coalesce((select string_agg('s' || session_no || ' ' || n, ', ' order by session_no) from (
            select s.session_no, count(*) n from public.curriculum_topic_proposals p join public.curriculum_sessions s on s.id = p.session_id
              join public.tracks t on t.id = p.track_id where t.code = 'digital' group by 1) x), 'none')
         || '; records 3-8 draft with note: ' || (select count(*) filter (where not is_approved and position('DIRA approval of 8 Nov 2026' in coalesce(assessment_notes, '')) > 0)
              from public.curriculum_sessions s join public.tracks t on t.id = s.track_id where t.code = 'digital' and s.session_no between 3 and 8)
  union all
  select 16, 'Data API grants (migration 38): signed-in users can read their profile; signed-out visitors have no table access; no grant without an RLS policy; no TRUNCATE/REFERENCES/TRIGGER',
         has_table_privilege('authenticated', 'public.profiles', 'select') and has_table_privilege('authenticated', 'public.profiles', 'update')
         and not exists (select 1 from information_schema.table_privileges where table_schema = 'public' and grantee = 'anon')
         and not exists (select 1 from information_schema.table_privileges where table_schema = 'public' and grantee = 'authenticated'
                          and privilege_type not in ('SELECT', 'INSERT', 'UPDATE', 'DELETE'))
         and not exists (select 1 from information_schema.table_privileges tp
                           join pg_class c on c.relname = tp.table_name and c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p')
                          where tp.table_schema = 'public' and tp.grantee = 'authenticated'
                            and not exists (select 1 from pg_policies p where p.schemaname = 'public' and p.tablename = tp.table_name and p.permissive = 'PERMISSIVE'
                                             and p.roles && array['authenticated', 'public']::name[] and (p.cmd = 'ALL' or p.cmd = tp.privilege_type)))
         and (select count(*) from information_schema.table_privileges where table_schema = 'public' and grantee = 'authenticated') >= 250
         and has_table_privilege('service_role', 'public.profiles', 'select'),
         (select count(distinct table_name) || ' tables/views granted to signed-in users (' || count(*) || ' privileges)'
            from information_schema.table_privileges where table_schema = 'public' and grantee = 'authenticated')
         || '; profiles readable: ' || has_table_privilege('authenticated', 'public.profiles', 'select')
         || '; signed-out table privileges: ' || (select count(*) from information_schema.table_privileges where table_schema = 'public' and grantee = 'anon')
)
select ord, item, case when coalesce(ok, false) then 'ok' else 'FAIL' end as status, detail from checks
union all
select 99, 'VERDICT', case when bool_and(coalesce(ok, false)) then 'READY' else 'NOT READY' end,
       case when bool_and(coalesce(ok, false)) then 'Installation verified. Next: open https://<your website>/setup and create the first Super Administrator (docs/deployment/INSTALL_GUIDE.md, part E).'
            else 'Do not set up the administrator yet. Send this table to Claude.' end
  from checks
order by ord;
